import fontkit from './vendor/fontkit.js';
import {PDFDocument,StandardFonts,rgb,degrees,PDFName,PDFBool} from './vendor/pdf-lib.js';
const MARK='@alof.emacao';
let fontBytes;export function setExportFont(bytes){fontBytes=bytes;}
async function unicodeFont(doc){doc.registerFontkit(fontkit);if(!fontBytes){const response=await fetch(new URL('./vendor/DejaVuSans.ttf',import.meta.url));if(!response.ok)throw Error('Não foi possível carregar a fonte do PDF. Tente novamente.');fontBytes=new Uint8Array(await response.arrayBuffer());}return doc.embedFont(fontBytes,{subset:true});}
const sanitize=value=>String(value??'').normalize('NFC').replace(/[\u2010-\u2015]/g,'-').replace(/→/g,' > ').replace(/[☑✓]/g,'[x]').replace(/☐/g,'[ ]').replace(/[\x00-\x08\x0b\x0c\x0e-\x1f]/g,' ');
export async function watermark(doc){const font=await doc.embedFont(StandardFonts.HelveticaBold);for(const page of doc.getPages()){if(page.node.get(PDFName.of('AlofWatermarked')))continue;const {x,y,width,height}=page.getCropBox(),size=Math.min(width/10,48),w=font.widthOfTextAtSize(MARK,size),angle=30*Math.PI/180;page.drawText(MARK,{x:x+width/2-w*Math.cos(angle)/2,y:y+height/2-w*Math.sin(angle)/2,size,font,color:rgb(.58,.48,.29),rotate:degrees(30),opacity:.13});page.node.set(PDFName.of('AlofWatermarked'),PDFBool.True);}return doc;}
export async function makePdf(model){const doc=await PDFDocument.create(),normal=await unicodeFont(doc),bold=normal;let page,y,pageNumber=0;function newPage(){page=doc.addPage([595.28,841.89]);y=770;pageNumber++;page.drawRectangle({x:44,y:802,width:507,height:2,color:rgb(.70,.57,.32)});page.drawText('MENTORIA ALOF.EMACAO',{x:44,y:816,size:9,font:bold,color:rgb(.25,.25,.25)});page.drawText(String(pageNumber),{x:535,y:28,size:9,font:normal});}
 function line(text,size=11,font=normal){if(y<60)newPage();page.drawText(text,{x:44,y,size,font,color:rgb(.10,.11,.09)});y-=size*1.5;}
 function paragraph(value,size=11,font=normal){for(const part of sanitize(value).split('\n')){let row='';for(const word of part.split(/\s+/)){if(!word)continue;let chunks=[word];if(font.widthOfTextAtSize(word,size)>505){chunks=[];let chunk='';for(const ch of word){if(font.widthOfTextAtSize(chunk+ch,size)>505){chunks.push(chunk);chunk='';}chunk+=ch;}if(chunk)chunks.push(chunk);}for(const chunk of chunks){if(row&&font.widthOfTextAtSize(row+' '+chunk,size)>505){line(row,size,font);row='';}row+=(row?' ':'')+chunk;}}line(row,size,font);}y-=5;}
 newPage();paragraph(model.title,21,bold);if(model.subtitle)paragraph(model.subtitle,10);for(const section of model.sections){if(section.breakBefore)newPage();if(section.title){if(y<110)newPage();paragraph(section.title,14,bold);}for(const text of section.lines||[])paragraph(text);y-=10;}await watermark(doc);doc.setTitle(sanitize(model.title));doc.setCreator('Mentoria alof.emacao');return doc.save();}
export async function stampMaterial(bytes,type='application/pdf'){let doc;if(type.includes('pdf')||new TextDecoder().decode(bytes.slice(0,5))==='%PDF-'){doc=await PDFDocument.load(bytes);}else if(type.startsWith('image/')){doc=await PDFDocument.create();const image=type.includes('png')?await doc.embedPng(bytes):await doc.embedJpg(bytes),p=doc.addPage([595.28,841.89]),scale=Math.min(507/image.width,753/image.height);p.drawImage(image,{x:(595.28-image.width*scale)/2,y:(841.89-image.height*scale)/2,width:image.width*scale,height:image.height*scale});}else throw Error('Para exportar este material com marca d’água, o mentor precisa disponibilizar a versão em PDF.');await watermark(doc);return doc.save();}
